    function instructionGraphic(){return `<div class="instruction-graphic"><div class="instruction-example"><span>1</span><i class="mini-bubble"></i><i class="mini-bubble"></i><i class="mini-bubble"></i><i class="mini-bubble filled"></i><span class="instruction-arrow">⟵</span><b>ถูกวิธี</b></div><div class="instruction-example"><span>2</span><i class="mini-bubble"></i><i class="mini-bubble crossed"></i><i class="mini-bubble"></i><i class="mini-bubble"></i><span class="instruction-arrow">⟵</span><b>ผิดวิธี · ลบคำตอบเดิมให้สะอาดก่อนฝนใหม่</b></div></div>`}function questionPaperGrid(ex,interactive=false){const count=Number(ex.count||10),parts=Math.max(1,Math.min(Number(ex.parts||1),count)),perPart=Math.ceil(count/parts);return Array.from({length:parts},(_,part)=>{const from=part*perPart,to=Math.min(count,from+perPart);if(from>=count)return '';const qs=Array.from({length:to-from},(_,offset)=>{const i=from+offset,opts=answerOptions(ex),selected=(interactive?answerKeyDraft:ex.answers)?.[i];return `<div class="answer-line"><b>${String(i+1).padStart(2,'0')}</b><div>${opts.map(o=>interactive?`<button type="button" class="bubble key-bubble ${selected===o?'selected':''}" data-key-question="${i}" data-key-value="${esc(o)}" aria-label="ข้อ ${i+1} คำตอบ ${esc(o)}">${esc(o)}</button>`:`<span class="bubble">${esc(o)}</span>`).join('')}<small class="question-points">${ex.points||1} คะแนน</small></div></div>`}).join('');return `<section class="answer-part"><h4>${esc(ex.partNames?.[part]||`ตอนที่ ${part+1}`)}</h4><div class="answer-question-grid">${qs}</div></section>`}).join('')}
