  function renderAdmin(){const users=state.users;return `${pageHeader('ผู้ดูแลระบบ','จัดการบัญชีผู้ใช้งานและการเชื่อมต่อระบบ',`<button class="btn btn-primary" data-action="new-user"><i class="fa-solid fa-user-plus"></i>เพิ่มผู้ใช้งาน</button>`)}<div class="stats-grid"><div class="stat-card"><div class="stat-head">ผู้ใช้งานทั้งหมด <span class="stat-icon"><i class="fa-solid fa-users"></i></span></div><div class="stat-value">${users.length}</div><div class="stat-foot">บัญชีในระบบนี้</div></div><div class="stat-card"><div class="stat-head">ผู้ดูแลระบบ <span class="stat-icon"><i class="fa-solid fa-user-shield"></i></span></div><div class="stat-value">${users.filter(x=>x.role==='admin').length}</div><div class="stat-foot">สิทธิ์ผู้ดูแล</div></div><div class="stat-card"><div class="stat-head">ชั้นเรียน <span class="stat-icon"><i class="fa-solid fa-people-roof"></i></span></div><div class="stat-value">${state.classes.length}</div><div class="stat-foot">ข้อมูลระบบ</div></div><div class="stat-card"><div class="stat-head">ชุดข้อสอบ <span class="stat-icon"><i class="fa-regular fa-file-lines"></i></span></div><div class="stat-value">${state.exams.length}</div><div class="stat-foot">ข้อมูลระบบ</div></div></div><div class="content-card"><div class="toolbar"><b class="me-auto">บัญชีผู้ใช้งาน</b><span class="filter-caption">สิทธิ์และสถานะบัญชี</span></div><div class="table-wrap"><table class="data-table"><thead><tr><th>ผู้ใช้งาน</th><th>ชื่อ-สกุล</th><th>สิทธิ์</th><th>จัดการ</th></tr></thead><tbody>${users.map(u=>`<tr><td><div class="user-chip"><span class="mini-avatar">${esc((u.name||u.username).slice(0,1))}</span><b>${esc(u.username)}</b></div></td><td>${esc(u.name||'—')}</td><td><span class="${u.role==='admin'?'admin-badge':'pill gray'}">${u.role==='admin'?'ผู้ดูแลระบบ':'ผู้ใช้งาน'}</span></td><td><div class="table-actions"><button title="สลับสิทธิ์" data-action="toggle-role" data-id="${esc(u.username)}"><i class="fa-solid fa-user-shield"></i></button><button title="ลบผู้ใช้" data-action="delete-user" data-id="${esc(u.username)}"><i class="fa-regular fa-trash-can"></i></button></div></td></tr>`).join('')}</tbody></table></div></div><div class="setting-grid mt-3"><section class="content-card setting-section"><h3>แบรนด์โรงเรียน</h3><p class="subtext">จัดการโลโก้และชื่อโรงเรียนได้จากหน้าการตั้งค่า</p><button class="btn btn-light" data-action="go-settings">เปิดการตั้งค่า</button></section><section class="content-card setting-section"><h3>Google Sheets & Drive</h3><p class="subtext">กำหนดรหัสปลายทางและตั้งค่า Apps Script เพื่อเชื่อมต่อการจัดเก็บ</p><button class="btn btn-light" data-action="go-settings">ตั้งค่าการจัดเก็บ</button></section></div>`}
  function confirm(title,text,action){$('#confirmTitle').textContent=title;$('#confirmText').textContent=text;pendingConfirm=action;bootstrap.Modal.getOrCreateInstance($('#confirmModal')).show()}
