  function stopCamera(){if(cameraStream){cameraStream.getTracks().forEach(track=>track.stop());cameraStream=null}}
  let cameraFacing='environment';
  async function startCamera(){const status=$('#cameraStatus'),video=$('#scanVideo');if(!video)return;if(!navigator.mediaDevices?.getUserMedia){if(status)status.textContent='เบราว์เซอร์นี้ไม่รองรับกล้อง กรุณาเปิดผ่าน HTTPS หรือ localhost';return}try{cameraStream=await navigator.mediaDevices.getUserMedia({audio:false,video:{facingMode:{ideal:cameraFacing},width:{ideal:1920},height:{ideal:1080}}});video.srcObject=cameraStream;await video.play();if(status)status.textContent='วางกระดาษให้ครบทั้ง 4 จุดในกรอบ แล้วกดถ่ายภาพ'}catch(err){cameraStream=null;if(status)status.textContent=err.name==='NotAllowedError'?'ยังไม่ได้อนุญาตใช้กล้อง กรุณาเปิดสิทธิ์กล้องให้เว็บไซต์':'เปิดกล้องไม่สำเร็จ กรุณาตรวจสอบสิทธิ์และการเชื่อมต่อกล้อง'}}
  function renderScanner(){const ex=selectedExam();if(!ex){pageMode='';return renderExam()}return `${pageHeader('สแกนกระดาษคำตอบ',`กำลังเตรียมกล้องสำหรับ ${esc(ex.name)}`,`<button class="btn btn-light" data-action="flip-camera"><i class="fa-solid fa-camera-rotate"></i>สลับกล้อง</button><button class="btn btn-primary" data-action="capture-scan"><i class="fa-solid fa-camera"></i>ถ่ายภาพ</button>`)}<div class="scanner-layout"><label class="scan-save-option"><input type="checkbox" id="saveScanImage" checked><span><b>บันทึกภาพไว้ใน Google Drive</b><small>ภาพจะถูกจัดเก็บในโฟลเดอร์ปีปัจจุบัน และข้อมูลการสแกนซิงก์ไป Google Sheets</small></span></label><div class="scanner-view"><video id="scanVideo" autoplay muted playsinline></video><div class="scan-guide"><div class="scan-target"><i class="scan-corner tl"></i><i class="scan-corner tr"></i><i class="scan-corner bl"></i><i class="scan-corner br"></i><span class="scan-crosshair"></span><span class="scan-hint">จัดมุมกระดาษให้ตรงกับจุดทั้ง 4 มุม</span></div></div><canvas id="scanCanvas" class="d-none"></canvas><div class="camera-status" id="cameraStatus">กำลังขออนุญาตใช้กล้อง…</div></div><aside class="scanner-help"><div class="scan-help-icon"><i class="fa-solid fa-crosshairs"></i></div><h3>จัดแนวกระดาษให้แม่นยำ</h3><ol><li>วางกระดาษบนพื้นเรียบ สีตัดกับกระดาษ</li><li>ให้แสงสว่างสม่ำเสมอและหลีกเลี่ยงเงาสะท้อน</li><li>จัดมุมกระดาษทั้งสี่ให้อยู่ในกรอบ</li><li>ถือกล้องให้นิ่ง แล้วแตะถ่ายภาพ</li></ol><div class="scan-note"><i class="fa-solid fa-circle-info"></i>รุ่นนี้ถ่ายและบันทึกภาพได้ แต่ยังไม่อ่านคำตอบหรือคำนวณคะแนนจากภาพโดยอัตโนมัติ</div><div class="scan-captured" id="scanCaptured"></div></aside></div>`}
  function captureScan(){const video=$('#scanVideo'),canvas=$('#scanCanvas'),status=$('#cameraStatus');if(!video||!cameraStream||!video.videoWidth){if(status)status.textContent='กล้องยังไม่พร้อม กรุณารอหรืออนุญาตการใช้งานกล้อง';return}canvas.width=video.videoWidth;canvas.height=video.videoHeight;canvas.getContext('2d').drawImage(video,0,0,canvas.width,canvas.height);canvas.classList.remove('d-none');const data=canvas.toDataURL('image/jpeg',.88),area=$('#scanCaptured');area.innerHTML=`<img src="${data}" alt="ภาพกระดาษที่ถ่าย"><small>จับภาพแล้ว · ${canvas.width} × ${canvas.height} px</small>`;if(state.settings.vibrate&&navigator.vibrate)navigator.vibrate(80);if(!$('#saveScanImage')?.checked){if(status)status.textContent='ถ่ายภาพแล้ว · เลือกไม่บันทึกไฟล์';area.querySelector('small').textContent='ภาพนี้อยู่ในหน้านี้เท่านั้น และจะหายเมื่อออกจากหน้า';return}if(!window.google?.script?.run){if(status)status.textContent='ถ่ายภาพแล้ว · อัปโหลด Drive ได้เมื่อเปิดแอปผ่าน Apps Script HTTPS';return}if(status)status.textContent='กำลังบันทึกภาพลง Google Drive…';const ex=selectedExam();google.script.run.withSuccessHandler(result=>{ex.scans=ex.scans||[];ex.scans.push({id:result.id,url:result.url,name:result.name,capturedAt:new Date().toISOString()});save();area.querySelector('small').textContent=`บันทึกภาพใน Drive แล้ว · ${canvas.width} × ${canvas.height} px`;if(status)status.textContent='บันทึกภาพลง Google Drive แล้ว'}).withFailureHandler(err=>{console.error(err);if(status)status.textContent='ถ่ายภาพแล้ว แต่บันทึก Drive ไม่สำเร็จ · ตรวจสิทธิ์ Google Drive'}).uploadQuizSuiteScan(data,ex.name,'image/jpeg')}  function selectedExam(){return state.exams.find(e=>e.id===currentExamId)}
  function readCsv(text){return text.split(/\r?\n/).map(s=>s.trim()).filter(Boolean).map((line,i)=>line.split(',').map(x=>x.trim())).filter((row,i)=>i>0||!row[0]?.includes('ชื่อจริง'))}
  function processCsv(text){const rows=readCsv(text);let added=0;rows.forEach(r=>{if(r.length<4||!r[0]||!r[1])return;const s={id:id('st'),first:r[0],last:r[1],number:r[2]||'',className:r[3]||'',room:r[4]||''};state.students.push(s);if(s.className&&!state.classes.some(c=>c.name===s.className))state.classes.push({id:id('cl'),name:s.className,level:s.className.split('/')[0],room:s.className.split('/')[1]||s.room});added++});save();msg(`นำเข้ารายชื่อนักเรียน ${added} คน`);finishForm()}
