  $('#pageContent').addEventListener('change',e=>{if(e.target.name==='paperSize'){$('.custom-paper-size',$('#examForm')).classList.toggle('d-none',e.target.value!=='custom');return}if(e.target.id==='allPrintFields'){$$('[name="printField"]',$('#examForm')).forEach(x=>x.checked=e.target.checked);return}if(e.target.name==='printField'){$('#allPrintFields').checked=$$('[name="printField"]',$('#examForm')).every(x=>x.checked);return}if(e.target.matches('.setting-toggle')){state.settings[e.target.dataset.setting]=e.target.checked;save();msg('บันทึกการตั้งค่าแล้ว')}});
